<template>
  <div>
    <div class="el-plus-select">
      <el-select v-bind="$attrs" v-on="$listeners" v-model="selectValue">
        <slot></slot>
      </el-select>
      <div class="tip" v-if="tip">{{ tip }}</div>
    </div>
  </div>
</template>
<script>
export default {
  name: 'ElPlusSelect',
  props: {
    value: {
      type: [String, Number, Boolean, Object, Array],
      default: null,
    },
    tip: {
      type: String,
      default: '',
    },
  },
  computed: {
    selectValue: {
      get() {
        return this.value
      },
      set(val) {
        this.$emit('input', val)
      },
    },
  },
  methods: {},
}
</script>
<style lang="less" scoped>
.el-plus-select {
  position: relative;
  display: inline-block;
  .tip {
    margin-top: 5px;
    font-size: 12px;
    color: #888;
  }
}
</style>
